def compute(vars):
    interest_and_penalties = vars["v1"]
    interest_income = vars["v2"]
    difference = interest_and_penalties - interest_income

    return {
        "value": difference,
        "trace": {
            "interest_and_penalties": interest_and_penalties,
            "interest_income": interest_income,
            "difference": difference,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "currency"
            }
        }
    }
